const dir = path.dirname(fileURLToPath(import.meta.url));
const db = new DatabaseSync(process.env.EASEDRIVE_DB_PATH || path.join(dir, 'easedrive.db'));
db.exec('PRAGMA journal_mode = WAL');
db.exec(fs.readFileSync(path.join(dir, 'schema.sql'), 'utf8'));
const userTableSql=db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name='users'").get()?.sql||'';
if(!userTableSql.includes("'owner'"))db.exec("PRAGMA foreign_keys=OFF; BEGIN IMMEDIATE; CREATE TABLE users_rebuilt (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('renter','staff','owner','admin')), verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); INSERT INTO users_rebuilt SELECT id,name,email,phone,password_hash,role,verified,created_at FROM users; DROP TABLE users; ALTER TABLE users_rebuilt RENAME TO users; COMMIT; PRAGMA foreign_keys=ON;");
function ensureColumns(table,columns){const existing=new Set(db.prepare(`PRAGMA table_info(${table})`).all().map(c=>c.name));for(const [name,definition] of columns)if(!existing.has(name))db.exec(`ALTER TABLE ${table} ADD COLUMN ${name} ${definition}`);}
ensureColumns('password_recovery',[['delivery_id','TEXT']]);
ensureColumns('vehicles',[['year','INTEGER'],['plate_number','TEXT'],['fuel_type',"TEXT NOT NULL DEFAULT 'Gasoline'"],['color','TEXT'],['requirements',"TEXT NOT NULL DEFAULT ''"],['availability_schedule',"TEXT NOT NULL DEFAULT ''"],['is_enabled','INTEGER NOT NULL DEFAULT 1']]);
ensureColumns('bookings',[['rejection_reason','TEXT'],['handover_condition','TEXT'],['return_condition','TEXT'],['damage_report','TEXT'],['handover_photo_url','TEXT'],['return_photo_url','TEXT']]);
ensureColumns('maintenance_records',[['maintenance_date','TEXT'],['scheduled_date','TEXT'],['receipt_url','TEXT']]);
const imageColumns=new Set(db.prepare('PRAGMA table_info(vehicle_images)').all().map(c=>c.name));
for(const [name,definition] of [['storage_path','TEXT'],['original_name',"TEXT NOT NULL DEFAULT ''"],['mime_type',"TEXT NOT NULL DEFAULT ''"],['file_size','INTEGER NOT NULL DEFAULT 0'],['sort_order','INTEGER NOT NULL DEFAULT 0'],['is_primary','INTEGER NOT NULL DEFAULT 0'],['moderation_status',"TEXT NOT NULL DEFAULT 'approved'"],['uploaded_by','INTEGER REFERENCES users(id)'],['created_at','TEXT'],['photo_type',"TEXT NOT NULL DEFAULT 'general'"]])if(!imageColumns.has(name))db.exec(`ALTER TABLE vehicle_images ADD COLUMN ${name} ${definition}`);
const uploadDir=path.resolve(dir,'uploads');
const transaction = fn => { db.exec('BEGIN IMMEDIATE'); try { const result=fn(); db.exec('COMMIT'); return result; } catch (error) { db.exec('ROLLBACK'); throw error; } };
const scalar = (sql,...params) => Object.values(db.prepare(sql).get(...params))[0];
const app = express();
app.use(cors({ origin: process.env.CLIENT_ORIGIN || 'http://localhost:5173' }));
app.use(express.json({ limit: '35mb' }));
const secret = process.env.JWT_SECRET || 'local-development-secret-change-before-deploy';
if (process.env.NODE_ENV === 'production' && !process.env.JWT_SECRET) throw new Error('JWT_SECRET must be configured in production.');
if (!!process.env.SUPABASE_URL !== !!process.env.SUPABASE_SECRET_KEY) throw new Error('Set both SUPABASE_URL and SUPABASE_SECRET_KEY to enable cloud photo storage.');
const log = db.prepare('INSERT INTO activity_logs(actor_id,action,entity,entity_id) VALUES(?,?,?,?)');
const notify = db.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)');
const fail = (res, status, error) => res.status(status).json({ error });
const tokenUser = req => { try { return jwt.verify((req.headers.authorization || '').replace(/^Bearer /, ''), secret); } catch { return null; } };
function auth(req,res,next) { const u=tokenUser(req); if(!u) return fail(res,401,'Please sign in.'); req.user=u; next(); }
function roles(...allowed) { return (req,res,next) => allowed.includes(req.user.role) ? next() : fail(res,403,'You do not have access to this action.'); }
const cleanUser = u => ({ id:u.id,name:u.name,email:u.email,phone:u.phone,role:u.role,verified:!!u.verified });
const recoveryOtpHash = (userId,code) => createHmac('sha256',secret).update(`password-recovery:${userId}:${code}`).digest('hex');
const hashResetToken = token => createHash('sha256').update(token).digest('hex');
const recoveryLimits = new Map();
function recoveryIpAllowed(ip,limit=12){const now=Date.now();const current=recoveryLimits.get(ip);if(!current||current.until<=now){recoveryLimits.set(ip,{count:1,until:now+60*60*1000});return true;}if(current.count>=limit)return false;current.count++;return true;}
function normalizePhone(phone){const value=String(phone||'').replace(/\s/g,'').replace(/[()-]/g,'');if(/^09[0-9]{9}$/.test(value))return `+63${value.slice(1)}`;if(/^\+639[0-9]{9}$/.test(value))return value;return '';}
function recoveryUserFor(identifier){const value=String(identifier||'').trim();if(value.includes('@'))return db.prepare('SELECT id,email,phone FROM users WHERE lower(email)=?').get(value.toLowerCase());const normalized=normalizePhone(value);if(!normalized)return null;const matches=db.prepare("SELECT id,email,phone FROM users WHERE phone IS NOT NULL AND phone<>''").all().filter(user=>normalizePhone(user.phone)===normalized);return matches.length===1?matches[0]:null;}
function recoveryProviderConfigError(channel){if(channel==='email')return process.env.RESEND_API_KEY&&process.env.EMAIL_FROM?'':'Email recovery is not configured. Set RESEND_API_KEY and EMAIL_FROM in the server .env file.';return process.env.SEMAPHORE_API_KEY?'':'SMS recovery is not configured. Set SEMAPHORE_API_KEY in the server .env file.';}
async function deliverRecoveryCode(user,channel,code){const text=`Your EaseDrive password reset code is ${code}. It expires in 5 minutes. If you did not request this, you can ignore this message.`;if(channel==='email'){const key=process.env.RESEND_API_KEY,from=process.env.EMAIL_FROM;if(!key||!from)throw Error('Email recovery delivery is not configured.');const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json'},body:JSON.stringify({from,to:[user.email],subject:'Your EaseDrive password reset code',text}),signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(`Email provider returned ${response.status}.`);return;}const key=process.env.SEMAPHORE_API_KEY,to=normalizePhone(user.phone);if(!key||!to)throw Error('SMS recovery delivery is not configured for this account.');const body=new URLSearchParams({apikey:key,number:to.replace(/^\+/,''),message:'Your EaseDrive password reset code is {otp}. It expires in 5 minutes. If you did not request this, you can ignore this message.',code});if(process.env.SEMAPHORE_SENDER_NAME)body.set('sendername',process.env.SEMAPHORE_SENDER_NAME);const response=await fetch('https://api.semaphore.co/api/v4/otp',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body,signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(`Semaphore returned ${response.status}.`);const result=await response.json();if(!Array.isArray(result)||result.some(message=>['failed','refunded'].includes(String(message.status).toLowerCase())))throw Error('Semaphore could not queue the SMS message.');}
const imagesFor=(vehicleId,{approvedOnly=false}={})=>db.prepare(`SELECT id,vehicle_id,image_url,original_name,mime_type,file_size,sort_order,is_primary,moderation_status,created_at,photo_type FROM vehicle_images WHERE vehicle_id=? ${approvedOnly?"AND moderation_status='approved'":""} ORDER BY is_primary DESC,sort_order,id`).all(vehicleId);
function decodeImage(input){const match=/^data:image\/(jpeg|jpg|png|webp);base64,([A-Za-z0-9+/=]+)$/.exec(input.data);if(!match)throw Error('Photos must be JPG, PNG, or WEBP images.');const buffer=Buffer.from(match[2],'base64');if(buffer.length>5*1024*1024)throw Error('Each photo must be 5 MB or smaller.');let ext,mime;if(buffer.length>=3&&buffer[0]===0xff&&buffer[1]===0xd8&&buffer[2]===0xff){ext='jpg';mime='image/jpeg'}else if(buffer.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))){ext='png';mime='image/png'}else if(buffer.length>=12&&buffer.toString('ascii',0,4)==='RIFF'&&buffer.toString('ascii',8,12)==='WEBP'){ext='webp';mime='image/webp'}else throw Error('The uploaded file content is not a valid JPG, PNG, or WEBP image.');return{buffer,ext,mime};}
async function storeImage(vehicleId,image){const decoded=decodeImage(image);const key=`vehicles/${vehicleId}/${randomUUID()}.${decoded.ext}`;let imageUrl;if(process.env.SUPABASE_URL&&process.env.SUPABASE_SECRET_KEY){const base=process.env.SUPABASE_URL.replace(/\/$/,'');const bucket=process.env.SUPABASE_STORAGE_BUCKET||'vehicle-photos';const encoded=key.split('/').map(encodeURIComponent).join('/');const result=await fetch(`${base}/storage/v1/object/${encodeURIComponent(bucket)}/${encoded}`,{method:'POST',headers:{apikey:process.env.SUPABASE_SECRET_KEY,'Content-Type':decoded.mime,'x-upsert':'false'},body:decoded.buffer});if(!result.ok)throw Error('Cloud photo upload failed. Check the server storage settings and public bucket.');imageUrl=`${base}/storage/v1/object/public/${encodeURIComponent(bucket)}/${encoded}`;}else{const target=path.join(uploadDir,key);await fsp.mkdir(path.dirname(target),{recursive:true});await fsp.writeFile(target,decoded.buffer,{flag:'wx'});imageUrl=`/uploads/${key}`;}return{imageUrl,storagePath:key,mime:decoded.mime,size:decoded.buffer.length,ext:decoded.ext};}
async function deleteStoredImage(storagePath){if(!storagePath)return;if(process.env.SUPABASE_URL&&process.env.SUPABASE_SECRET_KEY){const base=process.env.SUPABASE_URL.replace(/\/$/,'');const bucket=process.env.SUPABASE_STORAGE_BUCKET||'vehicle-photos';const encoded=storagePath.split('/').map(encodeURIComponent).join('/');await fetch(`${base}/storage/v1/object/${encodeURIComponent(bucket)}/${encoded}`,{method:'DELETE',headers:{apikey:process.env.SUPABASE_SECRET_KEY}}).catch(()=>{});}else await fsp.rm(path.join(uploadDir,storagePath),{force:true}).catch(()=>{});}
async function saveImages(vehicleId,userId,uploads,{startOrder=0,primaryIndex=0}={}){if(uploads.length>8)throw Error('Upload no more than 8 photos at a time.');const decoded=uploads.map(decodeImage);if(decoded.reduce((n,x)=>n+x.buffer.length,0)>24*1024*1024)throw Error('Photos must total 24 MB or less.');const saved=[];try{for(let i=0;i<uploads.length;i++){const file=await storeImage(vehicleId,uploads[i]);saved.push(file);db.prepare('INSERT INTO vehicle_images(vehicle_id,image_url,storage_path,original_name,mime_type,file_size,sort_order,is_primary,moderation_status,uploaded_by,photo_type) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(vehicleId,file.imageUrl,file.storagePath,path.basename(uploads[i].name),file.mime,file.size,startOrder+i,i===primaryIndex?1:0,'pending',userId,uploads[i].photoType||'general');}const primary=saved[primaryIndex];if(primary)db.prepare('UPDATE vehicles SET image_url=? WHERE id=?').run(primary.imageUrl,vehicleId);return imagesFor(vehicleId);}catch(error){for(const file of saved)await deleteStoredImage(file.storagePath);throw error;}}
function setPrimaryImage(vehicleId,imageId){db.prepare('UPDATE vehicle_images SET is_primary=0 WHERE vehicle_id=?').run(vehicleId);if(imageId)db.prepare('UPDATE vehicle_images SET is_primary=1 WHERE id=? AND vehicle_id=?').run(imageId,vehicleId);const primary=db.prepare('SELECT image_url FROM vehicle_images WHERE vehicle_id=? AND is_primary=1').get(vehicleId);db.prepare('UPDATE vehicles SET image_url=? WHERE id=?').run(primary?.image_url||'',vehicleId);}
app.get('/api/health',(_,res)=>res.json({status:'ok'}));
app.use('/uploads',express.static(uploadDir,{fallthrough:false,maxAge:'1d'}));
app.post('/api/auth/register', (req,res)=>{
  const parsed=z.object({name:z.string().trim().min(2).max(80),email:z.string().email().transform(v=>v.toLowerCase()),phone:z.string().max(30).optional(),password:z.string().min(8).max(100),role:z.enum(['renter','staff','owner']).default('renter'),address:z.string().trim().min(5).max(300).optional(),idDocument:z.string().max(7*1024*1024).optional(),profilePicture:z.string().max(7*1024*1024).optional()}).superRefine((x,ctx)=>{if(x.role==='owner'&&(!x.address||!x.idDocument))ctx.addIssue({code:'custom',message:'Car owner registration requires an address and valid ID photo.'})}).safeParse(req.body);
  if(!parsed.success) return fail(res,400,parsed.error.issues[0].message);
  try { const x=parsed.data;const idDocument=x.role==='owner'?decodeImage({data:x.idDocument}):null;const profilePicture=x.profilePicture?decodeImage({data:x.profilePicture}):null;const userId=transaction(()=>{const result=db.prepare('INSERT INTO users(name,email,phone,password_hash,role) VALUES(?,?,?,?,?)').run(x.name,x.email,x.phone||'',bcrypt.hashSync(x.password,12),x.role);if(x.role==='staff')db.prepare('INSERT INTO staff_profiles(user_id) VALUES(?)').run(result.lastInsertRowid);if(x.role==='owner')db.prepare('INSERT INTO owner_profiles(user_id,address,id_document,id_document_mime,profile_picture,profile_picture_mime) VALUES(?,?,?,?,?,?)').run(result.lastInsertRowid,x.address,idDocument.buffer,idDocument.mime,profilePicture?.buffer||null,profilePicture?.mime||null);log.run(result.lastInsertRowid,'account_created','user',result.lastInsertRowid);return result.lastInsertRowid;});const user=db.prepare('SELECT * FROM users WHERE id=?').get(userId);res.status(201).json({token:jwt.sign(cleanUser(user),secret,{expiresIn:'7d'}),user:cleanUser(user)}); }
  catch(e){ const duplicate=/UNIQUE constraint failed/.test(e.message); fail(res, duplicate?409:500,duplicate?'An account with that email already exists.':'Could not create account.'); }
});
app.post('/api/auth/login',(req,res)=>{ const p=z.object({email:z.string().email(),password:z.string().min(1)}).safeParse(req.body); if(!p.success)return fail(res,400,'Enter a valid email and password.'); const u=db.prepare('SELECT * FROM users WHERE email=?').get(p.data.email.toLowerCase()); if(!u||!bcrypt.compareSync(p.data.password,u.password_hash))return fail(res,401,'Email or password is incorrect.'); res.json({token:jwt.sign(cleanUser(u),secret,{expiresIn:'7d'}),user:cleanUser(u)}); });
const recoveryMessage='If an account matches those details, a code may arrive using the selected method. Enter it here only if you receive it.';
app.post('/api/auth/password-recovery/request',async(req,res)=>{
  const p=z.object({identifier:z.string().trim().min(5).max(254),channel:z.enum(['email','sms'])}).safeParse(req.body);
  if(!p.success)return fail(res,400,'Enter the email address or mobile number registered to your account and choose a delivery method.');
  if(!recoveryIpAllowed(req.ip))return fail(res,429,'Too many recovery requests. Wait before requesting another code.');
  const configError=recoveryProviderConfigError(p.data.channel);
  if(configError)return fail(res,503,configError);
  const user=recoveryUserFor(p.data.identifier);
  if(!user)return res.status(202).json({message:recoveryMessage});
  const now=Date.now(),previous=db.prepare('SELECT * FROM password_recovery WHERE user_id=?').get(user.id);
  if(previous?.otp_hash&&now-previous.sent_at<60_000)return res.status(202).json({message:recoveryMessage});
  const withinWindow=previous&&now-previous.window_started_at<60*60*1000;
  const count=withinWindow?previous.request_count:0;
  if(count>=5||(p.data.channel==='sms'&&!normalizePhone(user.phone)))return res.status(202).json({message:recoveryMessage});
  const code=String(randomInt(0,1_000_000)).padStart(6,'0');
  const deliveryId=randomUUID();
  db.prepare(`INSERT INTO password_recovery(user_id,channel,otp_hash,expires_at,attempts,sent_at,window_started_at,request_count,verified_at,reset_token_hash,reset_expires_at,delivery_id)
    VALUES(?,?, '',0,0,?,?,?,?,NULL,NULL,?) ON CONFLICT(user_id) DO UPDATE SET channel=excluded.channel,otp_hash='',expires_at=0,attempts=0,sent_at=excluded.sent_at,window_started_at=excluded.window_started_at,request_count=excluded.request_count,verified_at=NULL,reset_token_hash=NULL,reset_expires_at=NULL,delivery_id=excluded.delivery_id`)
    .run(user.id,p.data.channel,now,withinWindow?previous.window_started_at:now,count+1,deliveryId);
  try{
    await deliverRecoveryCode(user,p.data.channel,code);
    const stored=db.prepare('UPDATE password_recovery SET otp_hash=?,expires_at=? WHERE user_id=? AND delivery_id=?').run(recoveryOtpHash(user.id,code),Date.now()+5*60*1000,user.id,deliveryId);
    if(stored.changes!==1)throw Error('Recovery request expired before the code could be saved.');
    return res.status(202).json({message:recoveryMessage});
  }catch(error){
    console.error('Password recovery delivery failed:',error.message);
    return fail(res,502,p.data.channel==='email'?'We could not deliver the email code. Check the email provider configuration and try again.':'We could not deliver the SMS code. Check the SMS provider configuration and try again.');
  }
});
app.post('/api/auth/password-recovery/verify',(req,res)=>{
  const p=z.object({identifier:z.string().trim().min(5).max(254),code:z.string().regex(/^[0-9]{6}$/)}).safeParse(req.body);
  if(!p.success)return fail(res,400,'Enter the 6-digit code.');
  if(!recoveryIpAllowed(req.ip,30))return fail(res,429,'Too many attempts. Please try again later.');
  const user=recoveryUserFor(p.data.identifier);
  const recovery=user&&db.prepare('SELECT * FROM password_recovery WHERE user_id=?').get(user.id),now=Date.now();
  if(!recovery||recovery.expires_at<now||recovery.verified_at||recovery.attempts>=5||!recovery.otp_hash)return fail(res,400,'That code is invalid or expired. Request a new code and try again.');
  const candidate=recoveryOtpHash(user.id,p.data.code),matches=timingSafeEqual(Buffer.from(candidate,'hex'),Buffer.from(recovery.otp_hash,'hex'));
  if(!matches){db.prepare('UPDATE password_recovery SET attempts=attempts+1 WHERE user_id=?').run(user.id);return fail(res,400,'That code is invalid or expired. Request a new code and try again.');}
  const resetToken=randomBytes(32).toString('hex');
  db.prepare('UPDATE password_recovery SET otp_hash=?,expires_at=0,verified_at=?,reset_token_hash=?,reset_expires_at=? WHERE user_id=?').run('',now,hashResetToken(resetToken),now+15*60*1000,user.id);
  res.json({resetToken,message:'Code verified.'});
});
app.post('/api/auth/password-recovery/reset',(req,res)=>{
  const p=z.object({resetToken:z.string().regex(/^[a-f0-9]{64}$/),password:z.string().min(12).max(100).regex(/[a-z]/).regex(/[A-Z]/).regex(/[0-9]/).regex(/[^A-Za-z0-9]/),confirmPassword:z.string().min(1).max(100)}).safeParse(req.body);
  if(!p.success)return fail(res,400,'Use 12 or more characters with an uppercase letter, lowercase letter, number, and symbol.');
  if(p.data.password!==p.data.confirmPassword)return fail(res,400,'Your passwords do not match.');
  const row=db.prepare('SELECT user_id FROM password_recovery WHERE reset_token_hash=? AND reset_expires_at>? AND verified_at IS NOT NULL').get(hashResetToken(p.data.resetToken),Date.now());
  if(!row)return fail(res,400,'This password reset link has expired. Request a new code.');
  db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(bcrypt.hashSync(p.data.password,12),row.user_id);
  db.prepare('UPDATE password_recovery SET reset_token_hash=NULL,reset_expires_at=NULL,otp_hash=?,expires_at=0 WHERE user_id=?').run('',row.user_id);
  log.run(row.user_id,'password_recovered','user',row.user_id);
  res.json({message:'Your password has been successfully reset!'});
});
