app.get('/api/owner/profile',auth,roles('owner'),(req,res)=>{const profile=db.prepare('SELECT address,verification_status,verification_reason,profile_picture,profile_picture_mime FROM owner_profiles WHERE user_id=?').get(req.user.id);if(!profile)return fail(res,404,'Owner profile not found.');const user=db.prepare('SELECT name,email,phone,created_at FROM users WHERE id=?').get(req.user.id);res.json({profile:{...profile,profile_picture:profile.profile_picture?`data:${profile.profile_picture_mime};base64,${profile.profile_picture.toString('base64')}`:null},user});});
app.patch('/api/owner/profile',auth,roles('owner'),(req,res)=>{const p=z.object({name:z.string().trim().min(2).max(80),phone:z.string().max(30),address:z.string().trim().min(5).max(300),profilePicture:z.string().max(7*1024*1024).optional()}).safeParse(req.body);if(!p.success)return fail(res,400,'Check your name, phone number, and address.');let picture;try{picture=p.data.profilePicture?decodeImage({data:p.data.profilePicture}):null;}catch(e){return fail(res,400,e.message);}db.prepare('UPDATE users SET name=?,phone=? WHERE id=?').run(p.data.name,p.data.phone,req.user.id);db.prepare('UPDATE owner_profiles SET address=?,profile_picture=COALESCE(?,profile_picture),profile_picture_mime=COALESCE(?,profile_picture_mime) WHERE user_id=?').run(p.data.address,picture?.buffer||null,picture?.mime||null,req.user.id);res.json({message:'Owner profile updated.'});});
app.patch('/api/owner/password',auth,roles('owner'),(req,res)=>{const p=z.object({currentPassword:z.string().min(1),newPassword:z.string().min(8).max(100)}).safeParse(req.body);if(!p.success)return fail(res,400,'Enter your current password and a new password of at least 8 characters.');const user=db.prepare('SELECT password_hash FROM users WHERE id=?').get(req.user.id);if(!bcrypt.compareSync(p.data.currentPassword,user.password_hash))return fail(res,401,'Current password is incorrect.');db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(bcrypt.hashSync(p.data.newPassword,12),req.user.id);log.run(req.user.id,'password_changed','user',req.user.id);res.json({message:'Password updated.'});});
app.get('/api/vehicles',(req,res)=>{ const {q='',type='',location=''}=req.query; const rows=db.prepare("SELECT v.*,u.name AS owner_name,ROUND(AVG(r.rating),1) AS rating FROM vehicles v JOIN users u ON u.id=v.owner_id LEFT JOIN reviews r ON r.vehicle_id=v.id WHERE v.status='active' AND v.is_enabled=1 AND (?='' OR v.name LIKE ? OR v.brand LIKE ? OR v.model LIKE ? OR v.location LIKE ?) AND (?='' OR v.type=?) AND (?='' OR v.location LIKE ?) GROUP BY v.id ORDER BY v.created_at DESC").all(q,`%${q}%`,`%${q}%`,`%${q}%`,`%${q}%`,type,type,location,`%${location}%`).map(v=>({...v,image_url:imagesFor(v.id,{approvedOnly:true}).find(x=>x.is_primary)?.image_url||''})); res.json({vehicles:rows}); });
app.get('/api/vehicles/:id',(req,res)=>{const v=db.prepare("SELECT v.*,u.name AS owner_name,ROUND(AVG(r.rating),1) AS rating,COUNT(r.id) AS review_count FROM vehicles v JOIN users u ON u.id=v.owner_id LEFT JOIN reviews r ON r.vehicle_id=v.id WHERE v.id=? AND v.status='active' AND v.is_enabled=1 GROUP BY v.id").get(req.params.id); if(!v)return fail(res,404,'Vehicle not found.');const images=imagesFor(v.id,{approvedOnly:true});res.json({vehicle:{...v,image_url:images.find(x=>x.is_primary)?.image_url||'',images},reviews:db.prepare('SELECT r.*,u.name AS renter_name FROM reviews r JOIN users u ON u.id=r.renter_id WHERE vehicle_id=? ORDER BY r.created_at DESC').all(v.id)});});
app.post('/api/availability',(req,res)=>{const p=z.object({vehicleId:z.coerce.number().int().positive(),pickup:z.string().date(),returnDate:z.string().date()}).safeParse(req.body);if(!p.success)return fail(res,400,'Choose valid pickup and return dates.');if(p.data.returnDate<=p.data.pickup)return fail(res,400,'Return date must be after pickup.');const vehicle=db.prepare("SELECT 1 FROM vehicles WHERE id=? AND status='active' AND is_enabled=1").get(p.data.vehicleId);const overlap=db.prepare("SELECT 1 FROM bookings WHERE vehicle_id=? AND status IN ('payment_pending','pending','confirmed','active') AND pickup_date < ? AND return_date > ? UNION SELECT 1 FROM vehicle_availability WHERE vehicle_id=? AND unavailable_from < ? AND unavailable_to > ? LIMIT 1").get(p.data.vehicleId,p.data.returnDate,p.data.pickup,p.data.vehicleId,p.data.returnDate,p.data.pickup);res.json({available:!!vehicle&&!overlap});});
app.post('/api/bookings',auth,roles('renter'),(req,res)=>{const p=z.object({vehicleId:z.coerce.number().int().positive(),pickup:z.string().date(),returnDate:z.string().date()}).safeParse(req.body);if(!p.success)return fail(res,400,'Choose valid pickup and return dates.');if(p.data.returnDate<=p.data.pickup)return fail(res,400,'Return date must be after pickup.');try{const result=transaction(()=>{const v=db.prepare("SELECT * FROM vehicles WHERE id=? AND status='active' AND is_enabled=1").get(p.data.vehicleId);if(!v)throw Error('Vehicle is not available.');const overlap=db.prepare("SELECT 1 FROM bookings WHERE vehicle_id=? AND status IN ('payment_pending','pending','confirmed','active') AND pickup_date < ? AND return_date > ? UNION SELECT 1 FROM vehicle_availability WHERE vehicle_id=? AND unavailable_from < ? AND unavailable_to > ? LIMIT 1").get(v.id,p.data.returnDate,p.data.pickup,v.id,p.data.returnDate,p.data.pickup);if(overlap)throw Error('Those dates are no longer available.');const days=Math.ceil((new Date(p.data.returnDate)-new Date(p.data.pickup))/86400000);if(days<1||days>60)throw Error('Bookings must be between 1 and 60 days.');const subtotal=days*v.price_per_day,fee=Math.round(subtotal*.05),reference='ED-'+Date.now().toString(36).toUpperCase();const id=db.prepare('INSERT INTO bookings(reference,renter_id,vehicle_id,pickup_date,return_date,days,subtotal,service_fee,total) VALUES(?,?,?,?,?,?,?,?,?)').run(reference,req.user.id,v.id,p.data.pickup,p.data.returnDate,days,subtotal,fee,subtotal+fee).lastInsertRowid;const paymentId=db.prepare("INSERT INTO payments(booking_id,amount) VALUES(?,?)").run(id,subtotal+fee).lastInsertRowid;log.run(req.user.id,'booking_created','booking',id);notify.run(v.owner_id,'New booking request',`Booking ${reference} awaits payment verification.`);return{booking:db.prepare('SELECT * FROM bookings WHERE id=?').get(id),payment:db.prepare('SELECT * FROM payments WHERE id=?').get(paymentId)};});res.status(201).json(result);}catch(e){fail(res,409,e.message);}});
app.get('/api/bookings',auth,(req,res)=>{const owner=['staff','owner'].includes(req.user.role);const where=req.user.role==='admin'?'1=1':owner?'v.owner_id=?':'b.renter_id=?';const args=req.user.role==='admin'?[]:[req.user.id];const rows=db.prepare(`SELECT b.*,v.name AS vehicle_name,v.owner_id,u.name AS renter_name,u.phone AS renter_phone,p.status AS payment_status,p.proof_url FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN users u ON u.id=b.renter_id LEFT JOIN payments p ON p.booking_id=b.id WHERE ${where} ORDER BY b.created_at DESC`).all(...args).map(b=>({...b,image_url:imagesFor(b.vehicle_id,{approvedOnly:true}).find(x=>x.is_primary)?.image_url||''}));res.json({bookings:rows});});
app.post('/api/payments/:bookingId/proof',auth,roles('renter'),(req,res)=>{const p=z.object({proofUrl:z.string().url().max(1000)}).safeParse(req.body);if(!p.success)return fail(res,400,'Provide a valid payment receipt link.');const b=db.prepare('SELECT * FROM bookings WHERE id=? AND renter_id=?').get(req.params.bookingId,req.user.id);if(!b)return fail(res,404,'Booking not found.');db.prepare("UPDATE payments SET proof_url=? WHERE booking_id=? AND status='pending'").run(p.data.proofUrl,b.id);notify.run(db.prepare('SELECT owner_id FROM vehicles WHERE id=?').get(b.vehicle_id).owner_id,'Payment proof submitted',`Check booking ${b.reference}.`);res.json({message:'Receipt submitted. Payment remains pending until verified.'});});
app.patch('/api/bookings/:id/status',auth,(req,res)=>{const p=z.object({status:z.enum(['confirmed','rejected','active','completed','cancelled']),reason:z.string().trim().max(500).optional(),condition:z.string().trim().max(2000).optional(),conditionPhotoUrl:z.string().url().max(1000).optional(),damageReport:z.string().trim().max(2000).optional()}).safeParse(req.body);if(!p.success)return fail(res,400,'Invalid booking update.');if(p.data.status==='rejected'&&!p.data.reason)return fail(res,400,'Provide a reason when declining a booking.');const b=db.prepare('SELECT b.*,v.owner_id FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE b.id=?').get(req.params.id);if(!b)return fail(res,404,'Booking not found.');const isOwner=['staff','owner'].includes(req.user.role);if(req.user.role!=='admin'&&!(isOwner&&b.owner_id===req.user.id)&&!(req.user.role==='renter'&&b.renter_id===req.user.id&&p.data.status==='cancelled'))return fail(res,403,'You cannot update this booking.');if(isOwner&&p.data.status==='confirmed'&&db.prepare("SELECT status FROM payments WHERE booking_id=?").get(b.id)?.status!=='successful')return fail(res,409,'Payment must be verified by an administrator before accepting the booking.');const transitions={confirmed:['pending'],rejected:['pending','payment_pending'],active:['confirmed'],completed:['active'],cancelled:['payment_pending','pending','confirmed']};if(!(transitions[p.data.status]||[]).includes(b.status))return fail(res,409,`Cannot change ${b.status} to ${p.data.status}.`);if(['active','completed'].includes(p.data.status)&&!p.data.condition)return fail(res,400,'Record the vehicle condition before updating the rental.');const update=db.prepare('UPDATE bookings SET status=?,rejection_reason=CASE WHEN ? IS NULL THEN rejection_reason ELSE ? END,handover_condition=CASE WHEN ?=char(97,99,116,105,118,101) THEN ? ELSE handover_condition END,return_condition=CASE WHEN ?=char(99,111,109,112,108,101,116,101,100) THEN ? ELSE return_condition END,handover_photo_url=CASE WHEN ?=char(97,99,116,105,118,101) THEN ? ELSE handover_photo_url END,return_photo_url=CASE WHEN ?=char(99,111,109,112,108,101,116,101,100) THEN ? ELSE return_photo_url END,damage_report=COALESCE(?,damage_report) WHERE id=?');update.run(p.data.status,p.data.reason||null,p.data.reason||null,p.data.status,p.data.condition||null,p.data.status,p.data.condition||null,p.data.status,p.data.conditionPhotoUrl||null,p.data.status,p.data.conditionPhotoUrl||null,p.data.damageReport||null,b.id);const recipient=p.data.status==='cancelled'?b.owner_id:b.renter_id;notify.run(recipient,p.data.status==='rejected'?'Booking rejected':'Booking updated',p.data.status==='rejected'?`Booking ${b.reference} was declined: ${p.data.reason}`:`Booking ${b.reference} is now ${p.data.status}.`);log.run(req.user.id,'booking_status_changed','booking',b.id);res.json({message:'Booking updated.'});});
app.get('/api/owner/dashboard',auth,roles('owner'),(req,res)=>{const id=req.user.id;const own="owner_id=?";const monthly=db.prepare("SELECT COALESCE(sum(b.subtotal),0) AS total FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN payments p ON p.booking_id=b.id WHERE v.owner_id=? AND p.status='successful' AND strftime('%Y-%m',b.created_at)=strftime('%Y-%m','now')").get(id).total;const verified=db.prepare("SELECT COALESCE(sum(b.subtotal),0) AS total FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN payments p ON p.booking_id=b.id WHERE v.owner_id=? AND p.status='successful' AND b.status='completed'").get(id).total;const pendingPayments=db.prepare("SELECT COALESCE(sum(b.subtotal),0) AS total FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN payments p ON p.booking_id=b.id WHERE v.owner_id=? AND p.status='successful' AND b.status!='completed'").get(id).total;const profile=db.prepare('SELECT verification_status,verification_reason FROM owner_profiles WHERE user_id=?').get(id);res.json({role:'owner',verification:profile?.verification_status||'pending',verificationReason:profile?.verification_reason||'',vehicles:scalar('SELECT count(*) FROM vehicles WHERE owner_id=?',id),available:scalar("SELECT count(*) FROM vehicles WHERE owner_id=? AND status='active' AND is_enabled=1",id),rented:scalar("SELECT count(DISTINCT v.id) FROM vehicles v JOIN bookings b ON b.vehicle_id=v.id WHERE v.owner_id=? AND b.status='active'",id),pending:scalar("SELECT count(*) FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE v.owner_id=? AND b.status IN ('pending','payment_pending')",id),approved:scalar("SELECT count(*) FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE v.owner_id=? AND b.status='confirmed'",id),earnings:verified,monthly,upcoming:db.prepare("SELECT b.id,b.reference,b.pickup_date,b.return_date,v.name AS vehicle_name FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE v.owner_id=? AND b.status='confirmed' AND b.pickup_date>=date('now') ORDER BY b.pickup_date LIMIT 5").all(id),pendingPayments});});
app.get('/api/owner/earnings',auth,roles('owner'),(req,res)=>{const id=req.user.id;const rows=db.prepare("SELECT b.reference,b.created_at,b.subtotal,b.service_fee,b.total,b.status AS booking_status,p.status AS payment_status,v.name AS vehicle_name FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN payments p ON p.booking_id=b.id WHERE v.owner_id=? ORDER BY b.created_at DESC LIMIT 100").all(id).map(r=>({...r,owner_net:r.payment_status==='successful'?r.subtotal:0}));res.json({transactions:rows,availableForWithdrawal:0,payoutNotice:'Owner payout processing is not configured. Verified earnings are shown for reconciliation and are not available to withdraw.'});});
app.get('/api/dashboard',auth,(req,res)=>{if(req.user.role==='admin'){const count=sql=>scalar(sql);return res.json({role:'admin',users:count("SELECT count(*) FROM users WHERE role='renter'"),owners:count("SELECT count(*) FROM users WHERE role='owner'"),vehicles:count('SELECT count(*) FROM vehicles'),active:count("SELECT count(*) FROM bookings WHERE status='active'"),pending:count("SELECT count(*) FROM bookings WHERE status IN ('payment_pending','pending')"),completed:count("SELECT count(*) FROM bookings WHERE status='completed'"),revenue:count("SELECT COALESCE(sum(amount),0) FROM payments WHERE status='successful'")});}if(req.user.role==='staff'){return res.json({role:'staff',vehicles:scalar('SELECT count(*) FROM vehicles WHERE owner_id=?',req.user.id),pending:scalar("SELECT count(*) FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE v.owner_id=? AND b.status IN ('pending','payment_pending')",req.user.id),active:scalar("SELECT count(*) FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE v.owner_id=? AND b.status='active'",req.user.id),earnings:scalar("SELECT COALESCE(sum(p.amount),0) FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN vehicles v ON v.id=b.vehicle_id WHERE v.owner_id=? AND p.status='successful'",req.user.id)});}res.json({role:'renter',bookings:scalar('SELECT count(*) FROM bookings WHERE renter_id=?',req.user.id),active:scalar("SELECT count(*) FROM bookings WHERE renter_id=? AND status IN ('confirmed','active')",req.user.id),spent:scalar("SELECT COALESCE(sum(p.amount),0) FROM payments p JOIN bookings b ON b.id=p.booking_id WHERE b.renter_id=? AND p.status='successful'",req.user.id)});});
app.post('/api/vehicles',auth,roles('staff','owner'),async(req,res)=>{const p=z.object({name:z.string().trim().min(2).max(120),brand:z.string().trim().min(1).max(80),model:z.string().trim().min(1).max(80),type:z.string().min(1),location:z.string().trim().min(2).max(120),pricePerDay:z.coerce.number().int().positive(),seats:z.coerce.number().int().min(1).max(20),transmission:z.enum(['Automatic','Manual']),description:z.string().max(2000).default(''),year:z.coerce.number().int().min(1950).max(new Date().getFullYear()+1).optional(),plateNumber:z.string().trim().max(20).optional(),fuelType:z.string().trim().max(30).default('Gasoline'),color:z.string().trim().max(40).optional(),requirements:z.string().max(1000).default(''),availabilitySchedule:z.string().max(2000).default(''),imageUploads:z.array(z.object({name:z.string().min(1).max(180),data:z.string().min(40).max(7*1024*1024),photoType:z.string().max(40).optional()})).min(1).max(8),primaryIndex:z.coerce.number().int().min(0).default(0)}).safeParse(req.body);if(!p.success)return fail(res,400,p.error.issues[0].message);if(req.user.role==='owner'&&!db.prepare("SELECT 1 FROM owner_profiles WHERE user_id=? AND verification_status='approved'").get(req.user.id))return fail(res,403,'Complete owner account verification before submitting a vehicle listing.');const x=p.data;if(x.primaryIndex>=x.imageUploads.length)return fail(res,400,'Choose a valid primary photo.');let id;try{id=db.prepare('INSERT INTO vehicles(owner_id,name,brand,model,type,location,price_per_day,seats,transmission,description,year,plate_number,fuel_type,color,requirements,availability_schedule) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(req.user.id,x.name,x.brand,x.model,x.type,x.location,x.pricePerDay,x.seats,x.transmission,x.description,x.year||null,x.plateNumber||null,x.fuelType,x.color||null,x.requirements,x.availabilitySchedule).lastInsertRowid;await saveImages(id,req.user.id,x.imageUploads,{primaryIndex:x.primaryIndex});log.run(req.user.id,'vehicle_submitted','vehicle',id);res.status(201).json({message:'Vehicle and photos submitted for administrator approval.',vehicleId:id,images:imagesFor(id)});}catch(e){if(id)db.prepare('DELETE FROM vehicles WHERE id=?').run(id);fail(res,400,e.message||'Could not save this vehicle.');}});
app.get('/api/my-vehicles',auth,roles('staff','owner'),(req,res)=>res.json({vehicles:db.prepare('SELECT * FROM vehicles WHERE owner_id=? ORDER BY created_at DESC').all(req.user.id).map(v=>{const images=imagesFor(v.id);return{...v,image_url:images.find(x=>x.is_primary)?.image_url||'',images}})}));
app.post('/api/vehicles/:id/images',auth,roles('staff','owner'),async(req,res)=>{const vehicle=db.prepare('SELECT * FROM vehicles WHERE id=? AND owner_id=?').get(req.params.id,req.user.id);if(!vehicle)return fail(res,404,'Vehicle not found.');const p=z.object({imageUploads:z.array(z.object({name:z.string().min(1).max(180),data:z.string().min(40).max(7*1024*1024),photoType:z.string().max(40).optional()})).min(1).max(8),primaryIndex:z.coerce.number().int().min(-1).default(-1)}).safeParse(req.body);if(!p.success)return fail(res,400,p.error.issues[0].message);const current=imagesFor(vehicle.id);if(current.length+p.data.imageUploads.length>8)return fail(res,400,'A vehicle can have up to 8 photos.');try{const added=await saveImages(vehicle.id,req.user.id,p.data.imageUploads,{startOrder:current.length,primaryIndex:p.data.primaryIndex});if(p.data.primaryIndex>=0)setPrimaryImage(vehicle.id,added[current.length+p.data.primaryIndex]?.id);else if(!imagesFor(vehicle.id,{approvedOnly:true}).some(x=>x.is_primary))setPrimaryImage(vehicle.id,added[current.length]?.id);db.prepare("UPDATE vehicles SET status='pending' WHERE id=?").run(vehicle.id);log.run(req.user.id,'vehicle_photos_added','vehicle',vehicle.id);res.status(201).json({images:imagesFor(vehicle.id),message:'New photos submitted for review. Listing is hidden until approval.'});}catch(e){fail(res,400,e.message);}});
app.patch('/api/vehicles/:id/images/order',auth,roles('staff','owner'),(req,res)=>{const vehicle=db.prepare('SELECT id FROM vehicles WHERE id=? AND owner_id=?').get(req.params.id,req.user.id);if(!vehicle)return fail(res,404,'Vehicle not found.');const p=z.object({orderedIds:z.array(z.coerce.number().int().positive()).min(1).max(8),primaryId:z.coerce.number().int().positive()}).safeParse(req.body);if(!p.success)return fail(res,400,'Choose a valid image order and primary photo.');const ids=imagesFor(vehicle.id).map(x=>x.id);if(p.data.orderedIds.length!==ids.length||[...p.data.orderedIds].sort((a,b)=>a-b).some((id,i)=>id!==[...ids].sort((a,b)=>a-b)[i])||!p.data.orderedIds.includes(p.data.primaryId))return fail(res,400,'The photo order must include all images for this vehicle.');transaction(()=>{const update=db.prepare('UPDATE vehicle_images SET sort_order=? WHERE id=? AND vehicle_id=?');p.data.orderedIds.forEach((id,i)=>update.run(i,id,vehicle.id));setPrimaryImage(vehicle.id,p.data.primaryId);db.prepare("UPDATE vehicles SET status='pending' WHERE id=?").run(vehicle.id);});res.json({images:imagesFor(vehicle.id),message:'Photo order saved. Listing is pending photo review.'});});
app.delete('/api/vehicles/:id/images/:imageId',auth,async(req,res)=>{const image=db.prepare(`SELECT i.* FROM vehicle_images i JOIN vehicles v ON v.id=i.vehicle_id WHERE i.id=? AND i.vehicle_id=? AND (v.owner_id=? OR ?='admin')`).get(req.params.imageId,req.params.id,req.user.id,req.user.role);if(!image)return fail(res,404,'Photo not found.');await deleteStoredImage(image.storage_path);db.prepare('DELETE FROM vehicle_images WHERE id=?').run(image.id);const remain=imagesFor(req.params.id);setPrimaryImage(Number(req.params.id),remain.find(x=>x.moderation_status==='approved')?.id||remain[0]?.id);if(['staff','owner'].includes(req.user.role)||!imagesFor(Number(req.params.id),{approvedOnly:true}).length)db.prepare("UPDATE vehicles SET status='pending' WHERE id=?").run(req.params.id);log.run(req.user.id,'vehicle_photo_removed','vehicle',req.params.id);res.json({images:imagesFor(req.params.id),message:'Photo removed.'});});
app.patch('/api/vehicles/:id',auth,roles('staff','owner'),(req,res)=>{const old=db.prepare('SELECT * FROM vehicles WHERE id=? AND owner_id=?').get(req.params.id,req.user.id);if(!old)return fail(res,404,'Vehicle not found.');const p=z.object({name:z.string().min(2),brand:z.string().min(1),model:z.string().min(1),type:z.string().min(1),location:z.string().min(2),pricePerDay:z.coerce.number().int().positive(),seats:z.coerce.number().int().min(1).max(20),transmission:z.enum(['Automatic','Manual']),description:z.string().max(2000).default(''),year:z.coerce.number().int().min(1950).max(new Date().getFullYear()+1).nullable().optional(),plateNumber:z.string().max(20).optional(),fuelType:z.string().max(30).default('Gasoline'),color:z.string().max(40).optional(),requirements:z.string().max(1000).default(''),availabilitySchedule:z.string().max(2000).default('')}).safeParse(req.body);if(!p.success)return fail(res,400,p.error.issues[0].message);const x=p.data;db.prepare("UPDATE vehicles SET name=?,brand=?,model=?,type=?,location=?,price_per_day=?,seats=?,transmission=?,description=?,year=?,plate_number=?,fuel_type=?,color=?,requirements=?,availability_schedule=?,status=CASE WHEN status='maintenance' THEN status ELSE 'pending' END WHERE id=? AND owner_id=?").run(x.name,x.brand,x.model,x.type,x.location,x.pricePerDay,x.seats,x.transmission,x.description,x.year||null,x.plateNumber||null,x.fuelType,x.color||null,x.requirements,x.availabilitySchedule,req.params.id,req.user.id);log.run(req.user.id,'vehicle_updated','vehicle',old.id);res.json({message:'Vehicle changes submitted for administrator review.'});});
app.patch('/api/vehicles/:id/availability',auth,roles('staff','owner'),(req,res)=>{const p=z.boolean().safeParse(req.body.enabled);if(!p.success)return fail(res,400,'Choose whether this listing should be available.');const result=db.prepare('UPDATE vehicles SET is_enabled=? WHERE id=? AND owner_id=?').run(p.data?1:0,req.params.id,req.user.id);if(!result.changes)return fail(res,404,'Vehicle not found.');log.run(req.user.id,p.data?'vehicle_enabled':'vehicle_disabled','vehicle',req.params.id);res.json({message:p.data?'Vehicle listing enabled.':'Vehicle listing paused.'});});
app.delete('/api/vehicles/:id',auth,roles('staff','owner'),async(req,res)=>{const vehicle=db.prepare('SELECT * FROM vehicles WHERE id=? AND owner_id=?').get(req.params.id,req.user.id);if(!vehicle)return fail(res,404,'Vehicle not found.');if(db.prepare("SELECT 1 FROM bookings WHERE vehicle_id=? AND status IN ('payment_pending','pending','confirmed','active') LIMIT 1").get(vehicle.id))return fail(res,409,'A vehicle with an active or upcoming booking cannot be deleted.');for(const image of imagesFor(vehicle.id))await deleteStoredImage(image.storage_path);db.prepare('DELETE FROM vehicles WHERE id=? AND owner_id=?').run(vehicle.id,req.user.id);log.run(req.user.id,'vehicle_deleted','vehicle',vehicle.id);res.json({message:'Vehicle deleted.'});});
app.get('/api/vehicles/:id/maintenance',auth,roles('staff','owner'),(req,res)=>{const vehicle=db.prepare('SELECT id FROM vehicles WHERE id=? AND owner_id=?').get(req.params.id,req.user.id);if(!vehicle)return fail(res,404,'Vehicle not found.');res.json({records:db.prepare('SELECT * FROM maintenance_records WHERE vehicle_id=? AND owner_id=? ORDER BY COALESCE(scheduled_date,maintenance_date,created_at) DESC').all(vehicle.id,req.user.id)});});
app.post('/api/vehicles/:id/maintenance',auth,roles('staff','owner'),(req,res)=>{const v=db.prepare('SELECT * FROM vehicles WHERE id=? AND owner_id=?').get(req.params.id,req.user.id);if(!v)return fail(res,404,'Vehicle not found.');const p=z.object({description:z.string().trim().min(5).max(1000),maintenanceDate:z.string().date().optional(),scheduledDate:z.string().date().optional(),receiptUrl:z.string().url().max(1000).optional()}).safeParse(req.body);if(!p.success)return fail(res,400,'Provide a description and valid maintenance dates.');const id=db.prepare('INSERT INTO maintenance_records(vehicle_id,owner_id,description,maintenance_date,scheduled_date,receipt_url) VALUES(?,?,?,?,?,?)').run(v.id,req.user.id,p.data.description,p.data.maintenanceDate||null,p.data.scheduledDate||null,p.data.receiptUrl||null).lastInsertRowid;db.prepare("UPDATE vehicles SET status='maintenance',is_enabled=0 WHERE id=?").run(v.id);log.run(req.user.id,'maintenance_reported','maintenance',id);res.status(201).json({message:'Maintenance recorded. This vehicle is unavailable for new bookings.'});});
app.patch('/api/maintenance/:id/complete',auth,roles('staff','owner'),(req,res)=>{const record=db.prepare('SELECT * FROM maintenance_records WHERE id=? AND owner_id=?').get(req.params.id,req.user.id);if(!record)return fail(res,404,'Maintenance record not found.');db.prepare("UPDATE maintenance_records SET status='completed' WHERE id=?").run(record.id);const open=db.prepare("SELECT 1 FROM maintenance_records WHERE vehicle_id=? AND owner_id=? AND status='open' LIMIT 1").get(record.vehicle_id,req.user.id);if(!open)db.prepare("UPDATE vehicles SET status='pending' WHERE id=? AND owner_id=?").run(record.vehicle_id,req.user.id);res.json({message:'Maintenance marked complete. Listing requires administrator approval before becoming public.'});});
app.get('/api/notifications',auth,(req,res)=>res.json({notifications:db.prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50').all(req.user.id)}));
app.patch('/api/notifications/:id/read',auth,(req,res)=>{db.prepare('UPDATE notifications SET read_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?').run(req.params.id,req.user.id);res.json({message:'Marked read.'});});
app.get('/api/messages/:bookingId',auth,(req,res)=>{const b=db.prepare('SELECT b.*,v.owner_id FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE b.id=?').get(req.params.bookingId);if(!b)return fail(res,404,'Booking not found.');if(req.user.role!=='admin'&&req.user.id!==b.owner_id&&req.user.id!==b.renter_id)return fail(res,403,'No access to this conversation.');res.json({messages:db.prepare('SELECT m.*,u.name AS sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE booking_id=? ORDER BY m.created_at').all(b.id)});});
app.post('/api/messages/:bookingId',auth,roles('renter','staff','owner'),(req,res)=>{const b=db.prepare('SELECT b.*,v.owner_id FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id WHERE b.id=?').get(req.params.bookingId);if(!b||![b.owner_id,b.renter_id].includes(req.user.id))return fail(res,403,'No access to this conversation.');const p=z.string().trim().min(1).max(2000).safeParse(req.body.body);if(!p.success)return fail(res,400,'Message must be 1Ã¢â‚¬â€œ2000 characters.');const id=db.prepare('INSERT INTO messages(booking_id,sender_id,body) VALUES(?,?,?)').run(b.id,req.user.id,p.data).lastInsertRowid;notify.run(req.user.id===b.renter_id?b.owner_id:b.renter_id,'New message',`New message about booking ${b.reference}.`);res.status(201).json({message:db.prepare('SELECT * FROM messages WHERE id=?').get(id)});});
app.post('/api/reviews',auth,roles('renter'),(req,res)=>{const p=z.object({bookingId:z.coerce.number(),rating:z.coerce.number().int().min(1).max(5),comment:z.string().max(1000).default('')}).safeParse(req.body);if(!p.success)return fail(res,400,'Choose a rating from 1 to 5.');const b=db.prepare("SELECT * FROM bookings WHERE id=? AND renter_id=? AND status='completed'").get(p.data.bookingId,req.user.id);if(!b)return fail(res,409,'Only completed rentals can be reviewed.');try{db.prepare('INSERT INTO reviews(booking_id,renter_id,vehicle_id,rating,comment) VALUES(?,?,?,?,?)').run(b.id,req.user.id,b.vehicle_id,p.data.rating,p.data.comment);res.status(201).json({message:'Review submitted.'});}catch{fail(res,409,'This rental already has a review.');}});
app.get('/api/admin/overview',auth,roles('admin'),(req,res)=>res.json({users:db.prepare("SELECT u.id,u.name,u.email,u.role,u.verified,u.created_at,o.verification_status,o.verification_reason FROM users u LEFT JOIN owner_profiles o ON o.user_id=u.id WHERE u.role!='admin' ORDER BY u.created_at DESC LIMIT 100").all(),vehicles:db.prepare("SELECT v.*,u.name AS owner_name FROM vehicles v JOIN users u ON u.id=v.owner_id ORDER BY v.created_at DESC").all().map(v=>{const images=imagesFor(v.id);return{...v,image_url:images.find(x=>x.is_primary)?.image_url||'',images}}),logs:db.prepare('SELECT l.*,u.name AS actor_name FROM activity_logs l LEFT JOIN users u ON u.id=l.actor_id ORDER BY l.created_at DESC LIMIT 30').all()}));
app.get('/api/admin/users/:id/id-document',auth,roles('admin'),(req,res)=>{const profile=db.prepare('SELECT id_document,id_document_mime FROM owner_profiles WHERE user_id=?').get(req.params.id);if(!profile)return fail(res,404,'Owner ID document not found.');res.type(profile.id_document_mime).set('Cache-Control','private, no-store').send(profile.id_document);});
app.patch('/api/admin/users/:id/verification',auth,roles('admin'),(req,res)=>{const p=z.object({status:z.enum(['approved','rejected']),reason:z.string().trim().max(500).optional()}).safeParse(req.body);if(!p.success)return fail(res,400,'Choose an approval decision.');const profile=db.prepare('SELECT user_id FROM owner_profiles WHERE user_id=?').get(req.params.id);if(!profile)return fail(res,404,'Owner registration not found.');if(p.data.status==='rejected'&&!p.data.reason)return fail(res,400,'Provide a reason for rejection.');transaction(()=>{db.prepare('UPDATE owner_profiles SET verification_status=?,verification_reason=? WHERE user_id=?').run(p.data.status,p.data.reason||null,req.params.id);db.prepare('UPDATE users SET verified=? WHERE id=? AND role=\'owner\'').run(p.data.status==='approved'?1:0,req.params.id);notify.run(req.params.id,'Owner verification updated',p.data.status==='approved'?'Your owner account is verified and may publish vehicle listings.':`Your owner verification needs attention: ${p.data.reason}`);});log.run(req.user.id,`owner_verification_${p.data.status}`,'user',req.params.id);res.json({message:`Owner verification ${p.data.status}.`});});
app.patch('/api/admin/vehicles/:id',auth,roles('admin'),(req,res)=>{const p=z.enum(['active','rejected','maintenance']).safeParse(req.body.status);if(!p.success)return fail(res,400,'Invalid vehicle status.');if(p.data==='active'){const owner=db.prepare('SELECT u.role,u.verified FROM vehicles v JOIN users u ON u.id=v.owner_id WHERE v.id=?').get(req.params.id);if(!owner)return fail(res,404,'Vehicle not found.');if(owner.role==='owner'&&!owner.verified)return fail(res,409,'Verify the vehicle owner before approving this listing.');const counts=db.prepare("SELECT sum(moderation_status='approved') AS approved,sum(moderation_status='pending') AS pending FROM vehicle_images WHERE vehicle_id=?").get(req.params.id);if(!counts?.approved)return fail(res,409,'Approve at least one vehicle photo before approving this listing.');if(counts.pending)return fail(res,409,'Review every uploaded photo before approving this listing.');}db.prepare('UPDATE vehicles SET status=? WHERE id=?').run(p.data,req.params.id);const v=db.prepare('SELECT owner_id,name FROM vehicles WHERE id=?').get(req.params.id);if(v)notify.run(v.owner_id,'Vehicle listing updated',`${v.name} is ${p.data}.`);log.run(req.user.id,'vehicle_moderated','vehicle',req.params.id);res.json({message:'Vehicle status updated.'});});
app.patch('/api/admin/images/:id/review',auth,roles('admin'),(req,res)=>{const p=z.enum(['approved','rejected']).safeParse(req.body.status);if(!p.success)return fail(res,400,'Choose approved or rejected.');const image=db.prepare('SELECT * FROM vehicle_images WHERE id=?').get(req.params.id);if(!image)return fail(res,404,'Photo not found.');db.prepare('UPDATE vehicle_images SET moderation_status=? WHERE id=?').run(p.data,image.id);if(p.data==='rejected'&&image.is_primary){const next=imagesFor(image.vehicle_id).find(x=>x.moderation_status==='approved'&&x.id!==image.id);setPrimaryImage(image.vehicle_id,next?.id);}if(p.data==='approved'&&!imagesFor(image.vehicle_id,{approvedOnly:true}).some(x=>x.is_primary))setPrimaryImage(image.vehicle_id,image.id);if(!imagesFor(image.vehicle_id,{approvedOnly:true}).length)db.prepare("UPDATE vehicles SET status='pending' WHERE id=?").run(image.vehicle_id);log.run(req.user.id,'vehicle_photo_reviewed','vehicle_image',image.id);res.json({message:`Photo ${p.data}.`});});
app.patch('/api/admin/users/:id/verify',auth,roles('admin'),(req,res)=>{const v=req.body.verified?1:0;db.prepare('UPDATE users SET verified=? WHERE id=? AND role IN (\'staff\',\'renter\')').run(v,req.params.id);db.prepare('UPDATE staff_profiles SET verification_status=? WHERE user_id=?').run(v?'approved':'pending',req.params.id);notify.run(req.params.id,'Verification updated',v?'Your account has been verified.':'Your verification status was updated.');res.json({message:'Verification updated.'});});
app.patch('/api/admin/payments/:bookingId/verify',auth,roles('admin'),(req,res)=>{const p=z.object({status:z.enum(['successful','failed'])}).safeParse(req.body);if(!p.success)return fail(res,400,'Choose successful or failed.');const b=db.prepare('SELECT b.*,v.owner_id,p.id AS payment_id,p.proof_url FROM bookings b JOIN vehicles v ON v.id=b.vehicle_id JOIN payments p ON p.booking_id=b.id WHERE b.id=?').get(req.params.bookingId);if(!b)return fail(res,404,'Payment not found.');if(b.status!=='payment_pending')return fail(res,409,'This booking is no longer awaiting payment verification.');if(p.data.status==='successful'&&!b.proof_url)return fail(res,409,'A payment receipt must be submitted before verification.');transaction(()=>{db.prepare('UPDATE payments SET status=?,verified_by=?,verified_at=CURRENT_TIMESTAMP WHERE id=?').run(p.data.status,req.user.id,b.payment_id);db.prepare('UPDATE bookings SET status=? WHERE id=?').run(p.data.status==='successful'?'pending':'cancelled',b.id);db.prepare('INSERT INTO transactions(payment_id,kind,amount,note) VALUES(?,?,?,?)').run(b.payment_id,p.data.status,b.total,`Admin ${p.data.status} payment review`);notify.run(b.renter_id,p.data.status==='successful'?'Payment confirmed':'Payment could not be verified',`Payment for booking ${b.reference} was ${p.data.status}.`);notify.run(b.owner_id,p.data.status==='successful'?'Booking ready for review':'Booking request closed',`Booking ${b.reference} ${p.data.status==='successful'?'has verified payment':'was closed after payment verification failed'}.`);log.run(req.user.id,'payment_verified','payment',b.payment_id);});res.json({message:`Payment marked ${p.data.status}.`});});
app.use(express.static(path.resolve(dir,'../dist')));
app.get('*',(req,res,next)=>req.path.startsWith('/api/')?next():res.sendFile(path.resolve(dir,'../dist/index.html')));
const port=process.env.PORT||4000;app.listen(port,()=>console.log(`EaseDrive API listening on ${port}`));
